script:
(function () {
  'use strict';
  // Gross margin and markup from any two known values:
  //   profit = price - cost;  margin = profit / price;  markup = profit / cost
  //   price = cost / (1 - margin) = cost x (1 + markup);  cost = price x (1 - margin) = price / (1 + markup)
  //   markup = margin / (1 - margin);  margin = markup / (1 + markup)
  // Verified: cost $60, price $100 -> profit $40, margin 40%, markup 66.67%;
  // cost $100 at 50% markup -> price $150, margin 33.33%; cost $100 at 25% margin -> price $133.33,
  // markup 33.33%; price $80 at 20% margin -> cost $64; price $120 at 50% markup -> cost $80.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var TARGETS = [10, 15, 20, 25, 30, 35, 40, 50, 60, 70];
  var FIELDS = { cost: 'mgCostField', price: 'mgPriceField', margin: 'mgMarginField', markup: 'mgMarkupField', profit: 'mgProfitField' };

  // --- calc start
  // Returns { cost, price } or { error }. margin and markup are decimals.
  function solve(mode, v) {
    var cost, price;
    switch (mode) {
      case 'cost-price': cost = v.cost; price = v.price; break;
      case 'cost-margin':
        if (v.margin >= 1) return { error: 'A gross margin must be below 100%.' };
        cost = v.cost; price = v.cost / (1 - v.margin); break;
      case 'cost-markup':
        if (v.markup <= -1) return { error: 'A markup must be above -100%.' };
        cost = v.cost; price = v.cost * (1 + v.markup); break;
      case 'price-margin':
        if (v.margin >= 1) return { error: 'A gross margin must be below 100%.' };
        price = v.price; cost = v.price * (1 - v.margin); break;
      case 'price-markup':
        if (v.markup <= -1) return { error: 'A markup must be above -100%.' };
        price = v.price; cost = v.price / (1 + v.markup); break;
      case 'cost-profit': cost = v.cost; price = v.cost + v.profit; break;
      case 'price-profit': price = v.price; cost = v.price - v.profit; break;
      default: return { error: 'Choose what you know.' };
    }
    if (cost < 0) return { error: 'These values give a negative cost. Check the profit or margin you entered.' };
    if (price < 0) return { error: 'These values give a negative selling price. Check the profit or markup you entered.' };
    return { cost: cost, price: price };
  }

  function ratios(cost, price) {
    var profit = price - cost;
    return { profit: profit, margin: price > 0 ? profit / price : NaN, markup: cost > 0 ? profit / cost : NaN };
  }
  // --- calc end

  function pct(x) {
    return isFinite(x) ? (x * 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%' : '–';
  }

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  var OUT = ['mgMarginOut', 'mgMarkupOut', 'mgProfitOut', 'mgCostOut', 'mgPriceOut', 'mgRevenueTotal', 'mgCostTotal', 'mgProfitTotal'];

  function update() {
    var mode = document.getElementById('mgMode').value;
    var needed = mode.split('-');
    Object.keys(FIELDS).forEach(function (key) {
      document.getElementById(FIELDS[key]).hidden = needed.indexOf(key) === -1;
    });
    var v = { cost: num('mgCost'), price: num('mgPrice'), margin: num('mgMargin') / 100, markup: num('mgMarkup') / 100, profit: num('mgProfit') };
    var units = num('mgUnits');
    var names = { cost: 'cost', price: 'selling price', margin: 'margin', markup: 'markup', profit: 'profit' };
    var msg = '';
    needed.forEach(function (key) {
      if (!msg && (isNaN(v[key]) || Math.abs(v[key]) > 1e12)) msg = 'Enter a ' + names[key] + '.';
    });
    if (!msg && ((needed.indexOf('cost') > -1 && v.cost < 0) || (needed.indexOf('price') > -1 && v.price < 0)))
      msg = 'Cost and selling price cannot be negative.';
    if (!msg && (isNaN(units) || units < 0 || units > 1e9)) msg = 'Enter 0 or more units sold.';
    var r = msg ? null : solve(mode, v);
    if (r && r.error) msg = r.error;
    var error = document.getElementById('mgError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) {
      OUT.forEach(function (id) { document.getElementById(id).textContent = '–'; });
      document.getElementById('mgTable').innerHTML = '';
      return;
    }
    var q = ratios(r.cost, r.price);
    document.getElementById('mgMarginOut').textContent = pct(q.margin);
    document.getElementById('mgMarkupOut').textContent = pct(q.markup);
    document.getElementById('mgProfitOut').textContent = money.format(q.profit);
    document.getElementById('mgCostOut').textContent = money.format(r.cost);
    document.getElementById('mgPriceOut').textContent = money.format(r.price);
    document.getElementById('mgRevenueTotal').textContent = money.format(r.price * units);
    document.getElementById('mgCostTotal').textContent = money.format(r.cost * units);
    document.getElementById('mgProfitTotal').textContent = money.format(q.profit * units);
    document.getElementById('mgTable').innerHTML = TARGETS.map(function (m) {
      var price = r.cost / (1 - m / 100);
      return '<tr><td>' + m + '%</td><td>' + pct(m / (100 - m)) + '</td><td>' + money.format(price) + '</td><td>' +
             money.format(price - r.cost) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('mgForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
